-- Vertical Jump (8-week) programme seed
-- programme_key = vertical_jump_8w
-- 3 levels (beginner/intermediate/advanced) x 4 phases (2 weeks each = 8 weeks)
-- Periodization: General -> Special -> Specific strength (Baker 1996) + plyometric peaking (Saez de Villarreal 2009)

delete from public.pt_explosive_programmes where programme_key='vertical_jump_8w';

insert into public.pt_explosive_programmes
  (level, phase, phase_name, weeks_label, focus, methods, blocks,
   programme_key, programme_name, category, audience, short_blurb,
   weeks_per_phase, "references")
values
('beginner', 1, 'General Strength + Landing', 'Weeks 1-2', 'Build a strength base and learn to land — foundation before jumping volume (Baker 1996)', ARRAY['Resistance','Plyo','Isometric']::text[], '[{"name": "A. General Strength", "rows": [{"num": "1", "exercise": "Goblet / Back Squat", "reps": "8", "sets": 3, "velocity": "Controlled", "pct1rm": 0.65, "dropoff": null, "cluster_rest": "—", "set_rest": "120 sec", "method": "Resistance", "yellow_sub": "Drop 1 set", "red_sub": "Wall sit 3 x 30s"}, {"num": "2", "exercise": "Trap-bar / DB Deadlift", "reps": "8", "sets": 3, "velocity": "Controlled", "pct1rm": 0.65, "dropoff": null, "cluster_rest": "—", "set_rest": "120 sec", "method": "Resistance", "yellow_sub": "Keep", "red_sub": "Glute bridge 3 x 10"}, {"num": "3", "exercise": "Calf raise / pogo intro", "reps": "12", "sets": 2, "velocity": "Controlled", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "60 sec", "method": "Plyo", "yellow_sub": "Keep", "red_sub": "Keep"}, {"num": "4", "exercise": "Split-squat ISO", "reps": "5s ea leg", "sets": 2, "velocity": "Hold", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "60 sec", "method": "Isometric", "yellow_sub": "Keep", "red_sub": "Keep"}]}, {"name": "B. Landing mechanics (~30 contacts)", "rows": [{"num": "1", "exercise": "Box jump (step down, soft land)", "reps": "5", "sets": 3, "velocity": "Controlled land", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "90 sec", "method": "Plyo", "yellow_sub": "Lower box", "red_sub": "Keep"}, {"num": "2", "exercise": "CMJ technique (stick the landing)", "reps": "5", "sets": 3, "velocity": "Fast", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "90 sec", "method": "Plyo", "yellow_sub": "Keep", "red_sub": "Keep"}]}]'::jsonb, 'vertical_jump_8w', 'Vertical Jump (8-week)', 'explosive_power', 'athletic_explosive_power', '8-week vertical jump programme: General -> Special -> Specific strength (Baker 1996), then a plyometric peaking block. Combines strength + jump training (~2x the gain of either alone), mixes squat/countermovement/drop jumps and progresses foot-contact volume (Saez de Villarreal 2009).', 2, '[{"year": 2009, "citation": "Saez de Villarreal, Kellis, Kraemer, Izquierdo (2009). Determining Variables of Plyometric Training for Improving Vertical Jump Height: A Meta-Analysis", "journal": "J Strength Cond Res 23(2):495-506", "focus": "56 studies. Best gains: >10 weeks, >20 sessions, high intensity >50 jumps/session. Combining squat jump + countermovement jump + drop jump in a session beats a single jump type. Added external load gives NO extra benefit over bodyweight. Good and poor fitness benefit equally. Mean VJ gain ~3.9 cm / >7%."}, {"year": 1996, "citation": "Baker (1996). Improving Vertical Jump Performance Through General, Special, and Specific Strength Training", "journal": "J Strength Cond Res 10(2):131-136", "focus": "General strength (squats, pulls) builds the contractile base; special strength (jump squats at optimal load, power cleans/shrugs) converts strength to power; specific strength (loaded jumps, repetitive jumps, depth jumps) mimics the jump. Combined general + specific = ~2x the VJ improvement of either alone (Adams). Knee/hip/ankle extensors contribute 49/28/23% to a CMJ; force must be produced in ~350 ms."}, {"year": 2018, "citation": "Ramirez-Campillo et al. / combined strength + plyometric meta-analyses (youth soccer; water sports; adolescents; individual sports)", "journal": "Systematic reviews & meta-analyses 2014-2022", "focus": "Plyometric jump training reliably improves VJ, sprint, and change-of-direction. Combined strength + plyometric training outperforms either method alone. Drop-jump intensity scales with drop height (30-60 cm); short ground-contact ''reactive'' work emphasises stretch-shortening cycle and tendon stiffness. Progress volume (foot contacts) and intensity (drop height) across the block."}]'::jsonb),
('beginner', 2, 'Strength + Jump Intent', 'Weeks 3-4', 'Keep building strength, add fast jump intent (Baker special-strength intro)', ARRAY['Resistance','RFD','Plyo']::text[], '[{"name": "A. Strength + intent", "rows": [{"num": "1", "exercise": "Back / Goblet Squat", "reps": "6", "sets": 4, "velocity": "Fast intent", "pct1rm": 0.72, "dropoff": null, "cluster_rest": "—", "set_rest": "150 sec", "method": "Resistance", "yellow_sub": "3 sets", "red_sub": "Wall sit 3 x 30s"}, {"num": "2", "exercise": "RDL", "reps": "8", "sets": 3, "velocity": "Controlled", "pct1rm": 0.62, "dropoff": null, "cluster_rest": "—", "set_rest": "90 sec", "method": "Resistance", "yellow_sub": "Keep", "red_sub": "Reduce load"}, {"num": "3", "exercise": "Jump shrug (light)", "reps": "4", "sets": 3, "velocity": "Fast", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "90 sec", "method": "RFD", "yellow_sub": "Keep", "red_sub": "Iso shrug 3 x 5s"}]}, {"name": "B. Plyometrics SJ + CMJ (~40 contacts)", "rows": [{"num": "1", "exercise": "Squat Jump", "reps": "5", "sets": 3, "velocity": "Max", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "90 sec", "method": "Plyo", "yellow_sub": "Keep", "red_sub": "Keep"}, {"num": "2", "exercise": "Countermovement Jump", "reps": "5", "sets": 3, "velocity": "Max", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "90 sec", "method": "Plyo", "yellow_sub": "Keep", "red_sub": "Keep"}, {"num": "3", "exercise": "Broad jump", "reps": "3", "sets": 2, "velocity": "Max", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "120 sec", "method": "Plyo", "yellow_sub": "Keep", "red_sub": "Skip"}]}]'::jsonb, 'vertical_jump_8w', 'Vertical Jump (8-week)', 'explosive_power', 'athletic_explosive_power', '8-week vertical jump programme: General -> Special -> Specific strength (Baker 1996), then a plyometric peaking block. Combines strength + jump training (~2x the gain of either alone), mixes squat/countermovement/drop jumps and progresses foot-contact volume (Saez de Villarreal 2009).', 2, '[]'::jsonb),
('beginner', 3, 'Plyometric Volume', 'Weeks 5-6', 'Build jump volume with squat + countermovement jumps; low-box drop jumps (Saez de Villarreal)', ARRAY['Plyo','Resistance']::text[], '[{"name": "A. Combined plyometrics (~60 contacts)", "rows": [{"num": "1", "exercise": "Squat Jump", "reps": "5", "sets": 3, "velocity": "Max", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "90 sec", "method": "Plyo", "yellow_sub": "Keep", "red_sub": "Keep"}, {"num": "2", "exercise": "Countermovement Jump", "reps": "5", "sets": 3, "velocity": "Max", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "90 sec", "method": "Plyo", "yellow_sub": "Keep", "red_sub": "Keep"}, {"num": "3", "exercise": "Drop Jump (low box 20-30 cm)", "reps": "4", "sets": 3, "velocity": "Reactive", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "120 sec", "method": "Plyo", "yellow_sub": "Box jump", "red_sub": "Pogo hops"}, {"num": "4", "exercise": "Tuck jumps", "reps": "6", "sets": 2, "velocity": "Continuous", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "90 sec", "method": "Plyo", "yellow_sub": "Keep", "red_sub": "Skip"}]}, {"name": "B. Strength maintenance", "rows": [{"num": "1", "exercise": "Back / Goblet Squat", "reps": "5", "sets": 3, "velocity": "Controlled", "pct1rm": 0.75, "dropoff": null, "cluster_rest": "—", "set_rest": "150 sec", "method": "Resistance", "yellow_sub": "2 sets", "red_sub": "Keep"}, {"num": "2", "exercise": "Nordic / hamstring curl", "reps": "5", "sets": 3, "velocity": "Controlled", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "90 sec", "method": "Resistance", "yellow_sub": "Band-assisted", "red_sub": "Eccentric only"}]}]'::jsonb, 'vertical_jump_8w', 'Vertical Jump (8-week)', 'explosive_power', 'athletic_explosive_power', '8-week vertical jump programme: General -> Special -> Specific strength (Baker 1996), then a plyometric peaking block. Combines strength + jump training (~2x the gain of either alone), mixes squat/countermovement/drop jumps and progresses foot-contact volume (Saez de Villarreal 2009).', 2, '[]'::jsonb),
('beginner', 4, 'Reactive Peaking', 'Weeks 7-8', 'Express speed and reactivity, keep strength ticking over', ARRAY['Plyo','RFD','Resistance']::text[], '[{"name": "A. Reactive (~40 contacts)", "rows": [{"num": "1", "exercise": "Drop Jump (30 cm box)", "reps": "4", "sets": 3, "velocity": "Reactive — short contact", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "150 sec", "method": "Plyo", "yellow_sub": "Box jump", "red_sub": "Pogo hops"}, {"num": "2", "exercise": "Continuous hops", "reps": "6", "sets": 3, "velocity": "Reactive", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "120 sec", "method": "Plyo", "yellow_sub": "Keep", "red_sub": "Keep"}, {"num": "3", "exercise": "Max CMJ", "reps": "3", "sets": 3, "velocity": "Max", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "120 sec", "method": "Plyo", "yellow_sub": "Keep", "red_sub": "Keep"}]}, {"name": "B. Maintenance", "rows": [{"num": "1", "exercise": "Jump squat (light, fast)", "reps": "3", "sets": 3, "velocity": "Max velocity", "pct1rm": null, "dropoff": null, "cluster_rest": "—", "set_rest": "120 sec", "method": "RFD", "yellow_sub": "2 sets", "red_sub": "CMJ x 5"}, {"num": "2", "exercise": "Back / Goblet Squat (maintenance)", "reps": "3", "sets": 2, "velocity": "Fast intent", "pct1rm": 0.72, "dropoff": null, "cluster_rest": "—", "set_rest": "150 sec", "method": "Resistance", "yellow_sub": "Keep", "red_sub": "Skip"}]}]'::jsonb, 'vertical_jump_8w', 'Vertical Jump (8-week)', 'explosive_power', 'athletic_explosive_power', '8-week vertical jump programme: General -> Special -> Specific strength (Baker 1996), then a plyometric peaking block. Combines strength + jump training (~2x the gain of either alone), mixes squat/countermovement/drop jumps and progresses foot-contact volume (Saez de Villarreal 2009).', 2, '[]'::jsonb);

